import java.util.Arrays;
import java.util.Comparator;
import java.util.List;
import java.util.stream.Collectors;

public class Main {
    public static void main(String[] args) {
        List<Integer> skor = Arrays.asList(70, 95, 80, 95, 60, 88, 70);

        List<Integer> naik = skor.stream().sorted().collect(Collectors.toList());
        System.out.println(naik);

        List<Integer> top3 = skor.stream()
                .distinct()
                .sorted(Comparator.reverseOrder())
                .limit(3)
                .collect(Collectors.toList());
        System.out.println("Top 3: " + top3);

        List<Integer> sisa = skor.stream().skip(5).collect(Collectors.toList());
        System.out.println(sisa);
    }
}

